  --sidebar-accent-foreground: #eceef6;
  --sidebar-border: #2a2f45;
  --sidebar-ring: #f5b843;

  /* semantic: these carry meaning and are separate from the accent */
  --success: #2fb574;
  --success-foreground: #ffffff;
  --warning: #e4802b;
  --warning-foreground: #1b1e2b;
  --info: #4f7cf0;
