// The track of a progress meter. The fill colour lives on the indicator, never in an app stylesheet.
@Directive({
  selector: 'div[hlmProgress]',
  host: { 'data-slot': 'progress' },
})
export class HlmProgress {
  constructor() {
    classes(() => 'relative flex h-2 w-full items-center overflow-hidden rounded-full bg-muted');
  }
}

// The filled part of the track. The consumer sets its width with a [style.width.%] binding.
@Directive({
  selector: 'div[hlmProgressIndicator]',
  host: { 'data-slot': 'progress-indicator' },
})
export class HlmProgressIndicator {
  constructor() {
    classes(() => 'h-full rounded-full bg-primary transition-all');
  }
}

